// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }
//
// Events are applied strictly in seq order starting at startSeq. Events that
// arrive early are buffered until every lower seq has been applied. Duplicate
// ids (already applied or buffered) and stale seqs (already applied) are ignored.

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.nextSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this.buffered = new Map(); // seq -> event, received but not yet applied
    this.seenIds = new Set(); // ids that were applied or are buffered
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this.buffered.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    if (this.seenIds.has(event.id)) return [];
    if (event.seq < this.nextSeq) return [];
    if (this.buffered.has(event.seq)) return [];

    this.seenIds.add(event.id);
    this.buffered.set(event.seq, event);

    const applied = [];
    while (this.buffered.has(this.nextSeq)) {
      const next = this.buffered.get(this.nextSeq);
      this.apply(next);
      this.buffered.delete(this.nextSeq);
      this.lastSeq = next.seq;
      this.nextSeq += 1;
      applied.push(next);
    }
    return applied;
  }
}

