// Wire format for user profiles.
//
// v2 (current): { "v": 2, "name": "Ada", "contact": { "email": "ada@x.io" }, "tags": ["admin", "beta"] }
// v1 (legacy):  { "v": 1, "name": "Ada", "email": "ada@x.io", "tags": "admin,beta" }
//   - Records written before 2023 have no "v" field at all; treat them as v1.
//   - In v1, an empty tags string means no tags.
//   - Unknown top-level fields are preserved: they are kept on the deserialized
//     object and written back out by serialize().
//
// In-memory profile: { name: string, email: string, tags: string[], ...unknownFields }

export const CURRENT_VERSION = 2;

const KNOWN_V1 = new Set(['v', 'name', 'email', 'tags']);
const KNOWN_V2 = new Set(['v', 'name', 'contact', 'tags']);

function unknownFields(data, known) {
  const extra = {};
  for (const [k, val] of Object.entries(data)) if (!known.has(k)) extra[k] = val;
  return extra;
}

export function serialize(profile) {
  const { name, email, tags = [], ...rest } = profile;
  return JSON.stringify({
    ...rest,
    v: CURRENT_VERSION,
    name,
    contact: { email },
    tags: [...tags],
  });
}

export function deserialize(text) {
  const data = JSON.parse(text);
  const version = data.v ?? 1;
  if (version === 1) return fromV1(data);
  if (version === 2) return fromV2(data);
  throw new Error(`unsupported version: ${version}`);
}

function fromV1(data) {
  return {
    ...unknownFields(data, KNOWN_V1),
    name: data.name,
    email: data.email,
    tags: data.tags ? data.tags.split(',') : [],
  };
}

function fromV2(data) {
  let tags;
  if (Array.isArray(data.tags)) tags = [...data.tags];
  else if (typeof data.tags === 'string' && data.tags) tags = data.tags.split(',');
  else tags = [];
  return {
    ...unknownFields(data, KNOWN_V2),
    name: data.name,
    email: data.contact?.email,
    tags,
  };
}

